"""Slicer metadata extraction from G-code comments.

Slicers write their settings and estimates as comments. The formats handled here:

* Bambu Studio: a ``HEADER_BLOCK`` (``; total filament length [mm] : 123.4``,
  ``; model printing time: 11m 8s; total estimated time: 17m 22s``) and a
  ``CONFIG_BLOCK`` of ``; key = value`` lines.
* OrcaSlicer / PrusaSlicer / SuperSlicer: ``; generated by <name> <version>``
  plus ``; filament used [mm] = ...`` and
  ``; estimated printing time (normal mode) = 1h 2m 3s`` and ``; key = value``
  settings.
* Cura: ``;TIME:1234``, ``;Filament used: 1.23m``, ``;Layer height: 0.2``.

Every field is optional. Files with no recognisable comments simply produce an
empty :class:`SlicerMetadata`.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

__all__ = ["MetadataCollector", "SlicerMetadata", "parse_duration"]

_DURATION_PART = re.compile(r"(\d+(?:\.\d+)?)\s*([dhms])", re.IGNORECASE)
_UNIT_SECONDS = {"d": 86400.0, "h": 3600.0, "m": 60.0, "s": 1.0}

_SLICER_BANNER = re.compile(
    r"^(BambuStudio|OrcaSlicer|PrusaSlicer|SuperSlicer|Slic3r)\s+(\d[\w.+\-]*)", re.IGNORECASE
)
_GENERATED_BY = re.compile(r"^generated by\s+([A-Za-z0-9_]+)\s+(\S+)", re.IGNORECASE)
_CURA_BANNER = re.compile(r"^Generated with\s+(Cura)\w*\s+(\S+)", re.IGNORECASE)
_BAMBU_MODEL_TIME = re.compile(r"model printing time:\s*([^;]+)", re.IGNORECASE)
_BAMBU_TOTAL_TIME = re.compile(r"total estimated time:\s*([^;]+)", re.IGNORECASE)
_KEY_VALUE = re.compile(r"^([A-Za-z][^:=]{0,60}?)\s*[:=]\s*(.+)$")
_NUMBER = re.compile(r"[-+]?(?:\d+\.?\d*|\.\d+)")


def parse_duration(text: str) -> float | None:
    """Parse ``"1d 2h 3m 4s"`` style durations into seconds.

    Returns ``None`` when the text contains no duration parts.
    """
    parts = _DURATION_PART.findall(text)
    if not parts:
        return None
    return sum(float(value) * _UNIT_SECONDS[unit.lower()] for value, unit in parts)


def _numbers(text: str) -> list[float]:
    return [float(match) for match in _NUMBER.findall(text)]


@dataclass(slots=True)
class SlicerMetadata:
    """What the slicer said about the print. Lists are per filament/tool."""

    slicer: str | None = None
    slicer_version: str | None = None
    #: Slicer's total time estimate in seconds (includes start-up where the slicer does).
    estimated_time_s: float | None = None
    #: Bambu Studio's "model printing time" (excludes the preparation sequence).
    model_time_s: float | None = None
    filament_used_mm: list[float] = field(default_factory=list)
    filament_used_cm3: list[float] = field(default_factory=list)
    filament_used_g: list[float] = field(default_factory=list)
    layer_height: float | None = None
    first_layer_height: float | None = None
    nozzle_diameter: float | None = None
    filament_type: list[str] = field(default_factory=list)
    filament_density: list[float] = field(default_factory=list)
    filament_diameter: list[float] = field(default_factory=list)
    total_layers: int | None = None

    @property
    def is_empty(self) -> bool:
        """True when nothing at all was recognised."""
        return all(
            value is None or value == []
            for value in (getattr(self, name) for name in self.__slots__)
        )


class MetadataCollector:
    """Feed comment strings in file order; read :attr:`metadata` at the end.

    The first occurrence of each field wins, which keeps header values from
    being overwritten by look-alike comments deeper in the file.
    """

    def __init__(self) -> None:
        self.metadata = SlicerMetadata()

    def feed(self, comment: str) -> None:
        text = comment.strip()
        if not text:
            return
        meta = self.metadata

        if meta.slicer is None:
            for pattern in (_SLICER_BANNER, _GENERATED_BY, _CURA_BANNER):
                banner = pattern.match(text)
                if banner is not None:
                    meta.slicer, meta.slicer_version = banner.group(1), banner.group(2)
                    return

        if "printing time" in text or "estimated time" in text:
            model = _BAMBU_MODEL_TIME.search(text)
            total = _BAMBU_TOTAL_TIME.search(text)
            if model is not None and meta.model_time_s is None:
                meta.model_time_s = parse_duration(model.group(1))
            if total is not None and meta.estimated_time_s is None:
                meta.estimated_time_s = parse_duration(total.group(1))
            if model is not None or total is not None:
                return

        pair = _KEY_VALUE.match(text)
        if pair is None:
            return
        raw_key, value = pair.group(1).strip(), pair.group(2).strip()
        self._assign(raw_key, value)

    def _assign(self, raw_key: str, value: str) -> None:
        meta = self.metadata
        key = raw_key.lower()

        # Cura keys are matched case-sensitively: "TIME" is too generic otherwise.
        if raw_key == "TIME":
            if meta.estimated_time_s is None and (nums := _numbers(value)):
                meta.estimated_time_s = nums[0]
        elif raw_key == "Filament used":
            if not meta.filament_used_mm:
                meta.filament_used_mm = [
                    float(n) * 1000.0 for n in re.findall(r"([\d.]+)\s*m\b", value)
                ]
        elif raw_key == "LAYER_COUNT" or key in ("total layer number", "total layers count"):
            if meta.total_layers is None and (nums := _numbers(value)):
                meta.total_layers = int(nums[0])
        elif key in ("total filament length [mm]", "filament used [mm]"):
            if not meta.filament_used_mm:
                meta.filament_used_mm = _numbers(value)
        elif key in ("total filament volume [cm^3]", "filament used [cm3]"):
            if not meta.filament_used_cm3:
                meta.filament_used_cm3 = _numbers(value)
        elif key in ("total filament weight [g]", "filament used [g]"):
            if not meta.filament_used_g:
                meta.filament_used_g = _numbers(value)
        elif key.startswith("estimated printing time (normal"):
            if meta.estimated_time_s is None:
                meta.estimated_time_s = parse_duration(value)
        elif raw_key in ("layer_height", "Layer height"):
            # Case-sensitive on purpose: Bambu/Orca write "; LAYER_HEIGHT: 0.2" on
            # every layer, which must not masquerade as the global setting.
            if meta.layer_height is None and (nums := _numbers(value)):
                meta.layer_height = nums[0]
        elif key in ("first_layer_height", "initial_layer_print_height"):
            # PrusaSlicer allows a percentage here; only absolute values are kept.
            if meta.first_layer_height is None and "%" not in value and (nums := _numbers(value)):
                meta.first_layer_height = nums[0]
        elif key == "nozzle_diameter":
            if meta.nozzle_diameter is None and (nums := _numbers(value)):
                meta.nozzle_diameter = nums[0]
        elif key == "filament_type":
            if not meta.filament_type:
                meta.filament_type = [
                    part.strip().strip('"') for part in re.split(r"[;,]", value) if part.strip()
                ]
        elif key == "filament_density":
            if not meta.filament_density:
                meta.filament_density = _numbers(value)
        elif key == "filament_diameter" and not meta.filament_diameter:
            meta.filament_diameter = _numbers(value)
